let drafts=read('bluemint-drafts',[]),saved=read('bluemint-watch',[]),view='discover',filter='all',side='buy',selected=null;tokens=[...drafts,...tokens];const fmt=n=>n>=1e6?(n/1e6).toFixed(2)+'M':n>=1000?(n/1000).toFixed(1)+'K':n.toLocaleString();const money=n=>Number(n).toLocaleString(undefined,{maximumFractionDigits:2,minimumFractionDigits:2});
function spark(t,cls='spark'){const pts=Array.from({length:35},(_,i)=>`${i*10},${44-i*.7+Math.sin(i*1.8+t.id)*7+Math.cos(i*.8)*5}`).join(' ');return `<svg class="${cls}" viewBox="0 0 340 55" preserveAspectRatio="none" aria-label="Illustrative price trend"><polyline points="${pts}" fill="none" stroke="${t.change<0?'#c98299':'#6a9cff'}" stroke-width="1.5" vector-effect="non-scaling-stroke"/></svg>`}
function render(){let list=tokens.filter(t=>(view!=='watchlist'||saved.includes(t.id))&&(filter==='all'||t.status===filter)&&(`${t.name} ${t.ticker}`).toLowerCase().includes($('#search').value.toLowerCase()));let sort=$('#sort').value;if(sort==='cap'||sort==='volume')list.sort((a,b)=>b[sort]-a[sort]);if(sort==='new')list.sort((a,b)=>b.id-a.id);$('#marketTitle').innerHTML=`${view==='watchlist'?'Your watchlist':'Discover tokens'}<span class="count">${list.length}</span>`;$('#grid').innerHTML=list.length?list.map(t=>`<article class="token" tabindex="0" role="button" aria-label="Open ${esc(t.name)}" data-id="${t.id}"><div class="token-top"><div class="avatar" style="--art:${t.art}">${esc(t.symbol)}</div><div><h3>${esc(t.name)}</h3><span class="ticker">${esc(t.ticker)} <span style="color:#42516a">/</span> USDC</span></div><button class="star ${saved.includes(t.id)?'saved':''}" data-save="${t.id}" aria-label="${saved.includes(t.id)?'Remove from':'Add to'} watchlist" aria-pressed="${saved.includes(t.id)}">${saved.includes(t.id)?'★':'☆'}</button></div><p class="token-desc">${esc(t.desc)}</p>${spark(t)}<div class="numbers"><div><span>Market cap · USDC</span><b>${fmt(t.cap)}</b></div><div><span class="change ${t.change<0?'negative':''}">${t.change>0?'+':''}${t.change}%</span><span style="text-align:right">Vol ${fmt(t.volume)} USDC</span></div></div><div class="card-line"></div><div class="progress-meta"><span>${t.status==='draft'?'Local launch draft':t.status==='graduated'?' Graduated':'Bonding curve'}</span><b>${t.progress}%</b></div><div class="progress"><div style="width:${t.progress}%"></div></div><div class="card-bottom"><span class="liq-label">◈ 0.75% liquidity allocation</span><span>${esc(t.age)}</span></div></article>`).join(''):'<div class="empty">No tokens here yet.<br><br>Try another search or add a token to your watchlist.</div>';$$('[data-save]').forEach(b=>b.onclick=e=>{e.stopPropagation();let id=Number(b.dataset.save);saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];write('bluemint-watch',saved);render()});$$('.token').forEach(el=>{el.onclick=()=>detail(Number(el.dataset.id));el.onkeydown=e=>{if(e.target===el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.click()}}})}
const modal=$('#modal');function open(html){$('#modalContent').innerHTML=html;if(!modal.open)modal.showModal()}$('.close').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal)modal.close()};function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function liquidity(){open(`<div class="eyebrow blue">THE MINT</div><h2>Trading fees. Deeper liquidity.</h2><p class="modal-sub">Proposed policy for every BlueMint launch. No holder rewards. Each token funds its own liquidity.</p><div class="split"><span>Launchpad treasury</span><b>0.50%</b></div><div class="split"><span>Token liquidity strategy</span><b>0.75%</b></div><div class="split"><span>Launchpad fee subtotal</span><b>1.25%</b></div><div class="split"><span>Raydium trading fees</span><b>Additional · configuration-dependent</b></div><div class="steps"><p><b>01 · Accumulate</b><br>Track each token’s liquidity allocation separately. Pre-graduation allocations wait for an eligible pool.</p><p><b>02 · Buy and pair</b><br>Spend a calculated portion of USDC on that token. Retain the rest to pair with the purchased tokens.</p><p><b>03 · Add and lock</b><br>Deposit both assets into the existing token/USDC pool and lock the resulting LP position. Publish execution receipts.</p></div><div class="info-box">Preview only. The collector, keeper, vault and LP-lock contracts are not deployed. Fee availability must be verified for both LaunchLab and CPMM. Liquidity additions do not guarantee a price floor.</div>`)}$('#engine').onclick=liquidity;$('#feesFooter').onclick=liquidity;$('#about').onclick=liquidity;
$$('.nav').forEach(b=>b.onclick=()=>{if(b.dataset.page==='liquidity'){liquidity();return}view=b.dataset.page;$$('.nav').forEach(x=>x.classList.toggle('active',x===b));filter='all';$$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.filter==='all'));render();$('#markets').scrollIntoView({behavior:'smooth'})});$$('.tab').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('.tab').forEach(x=>x.classList.toggle('active',x===b));render()});$('#search').oninput=render;$('#sort').onchange=render;$('#explore').onclick=()=>$('#markets').scrollIntoView({behavior:'smooth'});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!modal.open){e.preventDefault();$('#search').focus()}});
