function launch(){open(`<div class="eyebrow blue">START SOMETHING NEW</div><h2>Launch your next idea.</h2><p class="modal-sub">Create a local launch draft. All markets are quoted in Circle USDC.</p><form id="launchForm"><div class="form-grid"><label class="field">Token name<input name="name" required maxlength="32" placeholder="e.g. Blue Hour"></label><label class="field">Ticker<input name="ticker" required maxlength="10" pattern="[A-Za-z0-9]{2,10}" placeholder="e.g. HOUR"></label></div><label class="field">Description<textarea name="desc" required maxlength="160" placeholder="What is your community about?"></textarea></label><div class="form-grid"><label class="field">Quote currency<input value="Circle USDC · Solana" readonly></label><label class="field">Seed liquidity commitment · USDC<input name="seed" type="number" min="0" max="1000000000" step="0.01" value="1000" required></label></div><div class="split"><span>Launchpad treasury</span><b>0.50%</b></div><div class="split"><span>Your token’s liquidity allocation</span><b>0.75%</b></div><div class="split"><span>Raydium fees</span><b>Additional</b></div><div class="info-box">Seed liquidity is a proposed commitment, not a developer purchase or deposit. Saving this draft does not mint a token or send funds. No holder rewards.</div><label style="font-size:12px;color:#a5b5ce;display:flex;gap:9px"><input type="checkbox" required> I understand this creates a local preview draft.</label><button class="primary full" type="submit">Create launch draft </button></form>`);$('#launchForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),ticker=f.get('ticker').toUpperCase();if(ticker==='USDC'){toast('Choose a distinct ticker for this token. USDC identifies the quote asset.');return}const t={id:Date.now(),name:f.get('name').trim(),ticker,symbol:ticker[0],desc:f.get('desc').trim(),seed:Number(f.get('seed')),art:'linear-gradient(135deg,#448cff,#142d62)',cap:0,volume:0,change:0,progress:0,age:'Draft',status:'draft'};if(!t.name||!t.desc)return;drafts.unshift(t);tokens.unshift(t);write('bluemint-drafts',drafts);filter='all';view='discover';$('#search').value='';$$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.filter==='all'));render();modal.close();toast('Launch draft saved on this device. No token minted.');$('#markets').scrollIntoView({behavior:'smooth'})}}$('#launch').onclick=launch;$('#launchBottom').onclick=launch;
function detail(id){selected=tokens.find(t=>t.id===id);side='buy';tradeView()}
function tradeView(){const t=selected;open(`<div class="detail-header"><div class="avatar" style="--art:${t.art}">${esc(t.symbol)}</div><div><h2>${esc(t.name)}</h2><span class="ticker">${esc(t.ticker)} / Circle USDC · ${t.status==='draft'?'Local draft':'Sample market'}</span></div></div>${spark(t,'detail-chart')}<div class="split"><span>Sample market cap</span><b>${fmt(t.cap)} USDC</b></div><div class="mode-tabs"><button class="${side==='buy'?'active':''}" id="buyMode">Buy</button><button class="${side==='sell'?'active':''}" id="sellMode">Sell</button></div><label class="field">${side==='buy'?'Spend':'Gross sale value'} · USDC<input id="amount" type="number" min="0.01" step="0.01" max="1000000000" value="100"></label><div style="display:flex;gap:8px;margin-bottom:18px">${[50,100,500,1000].map(n=>`<button class="text-btn" style="flex:1;background:#1a2538;border-radius:4px;padding:7px" data-amount="${n}">${n}</button>`).join('')}</div><label class="field">Illustrative Raydium fee · %<input id="rayFee" type="number" min="0" max="10" step="0.01" value="${t.status==='graduated'?'.25':'1'}"></label><div id="quote"></div><button class="primary full" id="simulate">Simulate ${side} </button><p class="modal-sub" style="font-size:10px">Illustrative fee calculation only. Raydium fee is an editable assumption, not a live quote. Excludes slippage, network costs and terminal fees. No wallet transaction.</p><div id="receipt"></div>`);$('#buyMode').onclick=()=>{side='buy';tradeView()};$('#sellMode').onclick=()=>{side='sell';tradeView()};$('#amount').oninput=quote;$('#rayFee').oninput=quote;$$('[data-amount]').forEach(b=>b.onclick=()=>{$('#amount').value=b.dataset.amount;quote()});$('#simulate').onclick=()=>{const amount=Number($('#amount').value),rf=Number($('#rayFee').value);if(!Number.isFinite(amount)||amount<=0||amount>1e9||!Number.isFinite(rf)||rf<0||rf>10){toast('Enter a valid amount and fee rate.');return}$('#receipt').innerHTML=`<div class="info-box receipt">Simulation complete · ${money(amount)} USDC ${side==='buy'?'spend':'gross sale value'}.<br>${money(amount*.005)} USDC treasury allocation · ${money(amount*.0075)} USDC liquidity allocation.<br>No tokens traded and no funds moved.</div>`};quote()}
function quote(){let a=Number($('#amount').value),r=Number($('#rayFee').value);if(!Number.isFinite(a)||a<0||!Number.isFinite(r)||r<0||r>10){$('#quote').innerHTML='<p class="modal-sub">Enter valid quote values.</p>';return}const fees=a*(.0125+r/100);$('#quote').innerHTML=`<div class="split"><span>Launchpad treasury · 0.50%</span><b>${money(a*.005)} USDC</b></div><div class="split"><span>Token liquidity · 0.75%</span><b>${money(a*.0075)} USDC</b></div><div class="split"><span>Assumed Raydium fee · ${r}%</span><b>${money(a*r/100)} USDC</b></div><div class="split"><span>${side==='buy'?'Net amount for token purchase':'Estimated net proceeds'} · before price impact</span><b>${money(a-fees)} USDC</b></div>`}
render();
